Experience: 2 years in Product based MNC
Hi i was approached by rcruiter 2 days back and I had my first interview:-

Round 1:  1) Given a m x n grid filled with non-negative numbers, find a path from top left to bottom right, which minimizes the sum of all numbers along its path.
Note: You can only move either down or right at any point in time.
Simple DP with grid question did it in 20 min with dp+memoization. Interviewer was satisfied and we moved on to next question
The next question was not so straight forward took few minutes to think and came up with a BFS approach to solve this 
2)  You are given an array of routes representing where route[i] is route of i th train that repeats forever. Every route contains one or more stations. You have been given a source station and destination station. Return minimum number of train a person must take to travel from source to destination.
// DS Problems
// DS Problems
// 100%
// 10
// C8

// Input: Train routes = [[4, 2, 12], [3, 26], [1, 10], [4, 26, 6]]
// src = 3
// dest = 12
// Output: 3
My code 
```
#include <bits/stdc++.h>
using namespace std;

#define ip pair<int,int>
#define mp make_pair
int solve(vector<int>adj[],int n,int src,int dst){
    queue<ip> q;
    q.push({src,0});
    set<int> st;
    st.insert(src);
    while(!q.empty()){
        ip front= q.front();
        int node= front.first;
        int dist= front.second;
        if(node==dst) return dist;
        q.pop();
        for(auto x:adj[node]){
            if(st.find(x)==st.end()){
                q.push({x,dist+1});
            }
        }
    }
    return -1;
}

int main() {
	// your code goes here
	vector<vector<int>> vec{{4, 2, 12,5}, {3, 26}, {1, 10}, {4, 26, 6}};
	int n=vec.size();
	vector<int> adj[100];
	for(int i=0;i<vec.size();i++){
	    for(int j=0;j<vec[i].size();j++){
	        for(int k=0;k<vec[i].size();k++){
	            if(vec[i][j]!=vec[i][k]){
	                adj[vec[i][j]].push_back(vec[i][k]);
	                adj[vec[i][k]].push_back(vec[i][j]);
	            }

	        }
	    }
	}
	int src=3;
	int dst=12;
	int x=solve(adj,n,src,dst);
	cout<<x;

}
```
